INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'signaly-svetofora-regulirovshika', 'Сигналы светофора и регулировщика', 'Круглые сигналы светофора имеют следующие значения: зелёный разрешает движение, жёлтый запрещает движение, кроме случая, когда водитель не может остановиться без экстренного торможения, красный запрещает движение. Сигналы регулировщика имеют приоритет перед сигналами светофора и требованиями дорожных знаков приоритета. Если сигналы светофора или регулировщика противоречат требованиям знаков приоритета, водители должны руководствоваться сигналами светофора или регулировщика.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='svetofor';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'proezd-peshehodnyh-perehodov', 'Проезд пешеходных переходов', 'На нерегулируемом пешеходном переходе водитель обязан уступить дорогу пешеходам, переходящим дорогу или вступившим на проезжую часть для осуществления перехода. При приближении к нерегулируемому пешеходному переходу водитель должен снизить скорость или остановиться, чтобы пропустить пешеходов. Запрещается движение задним ходом на пешеходных переходах, а также остановка и стоянка ближе 5 метров перед пешеходным переходом.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='pereskhod';
